const riskRecentDecisions = `-- name: RiskRecentDecisions :many
select d.id, d.score, d.outcome, d.reasons, c.label
from risk.risk_decisions d
left join risk.risk_cases c on c.decision_id = d.id
where d.checkpoint = $1 and d.created_at > $2
order by d.created_at desc
limit 5000
`

type RiskRecentDecisionsParams struct {
	Checkpoint string    `json:"checkpoint"`
	CreatedAt  time.Time `json:"createdAt"`
}

type RiskRecentDecisionsRow struct {
	ID      int64           `json:"id"`
	Score   int16           `json:"score"`
	Outcome string          `json:"outcome"`
	Reasons json.RawMessage `json:"reasons"`
	Label   *string         `json:"label"`
}

// Decisions of one checkpoint in the window, with the label of any case they opened (test bench).
func (q *Queries) RiskRecentDecisions(ctx context.Context, arg RiskRecentDecisionsParams) ([]RiskRecentDecisionsRow, error) {
	rows, err := q.db.Query(ctx, riskRecentDecisions, arg.Checkpoint, arg.CreatedAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []RiskRecentDecisionsRow{}
	for rows.Next() {
		var i RiskRecentDecisionsRow
		if err := rows.Scan(
			&i.ID,
			&i.Score,
			&i.Outcome,
			&i.Reasons,
			&i.Label,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

