const riskSubjectLabel = `-- name: RiskSubjectLabel :one
select coalesce(
  (select o.order_number from sales.orders o where o.id = $1::uuid),
  (select r.rma_number from aftersales.return_requests r where r.id = $1::uuid),
  (select t.reference from aftersales.trade_ins t where t.id = $1::uuid),
  (select s.display_name from sellers.sellers s where s.id = $1::uuid),
  (select u.first_name || ' ' || left(u.last_name, 1) || '.' from identity.users u where u.id = $1::uuid),
  '')::text as label
`

// A readable name for a case's subject: order or return number, trade-in reference, shop, or a
// masked person (first name and last initial).
func (q *Queries) RiskSubjectLabel(ctx context.Context, id uuid.UUID) (string, error) {
	row := q.db.QueryRow(ctx, riskSubjectLabel, id)
	var label string
	err := row.Scan(&label)
	return label, err
}

